package com.aligames.service;
import android.app.*;import android.os.*;import android.content.*;import android.net.*;import android.provider.MediaStore;import android.print.*;import android.webkit.*;import android.view.*;import java.util.*;
public class MainActivity extends Activity{
 WebView w; ValueCallback<Uri[]> cb; static final int PICK=7;
 public void onCreate(Bundle b){super.onCreate(b);w=new WebView(this);setContentView(w);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);w.setWebViewClient(new WebViewClient());w.setWebChromeClient(new WebChromeClient(){public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> c,FileChooserParams p){cb=c;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,PICK);return true;}});w.addJavascriptInterface(new Object(){@JavascriptInterface public void printPage(){runOnUiThread(()->{PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);pm.print("Ali Games Service",w.createPrintDocumentAdapter("AliGamesService"),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.NA_INDEX_4X6).setMinMargins(PrintAttributes.Margins.NO_MARGINS).build());});}},"AndroidPrint");w.loadUrl("file:///android_asset/index.html");}
 protected void onActivityResult(int r,int code,Intent d){super.onActivityResult(r,code,d);if(r==PICK&&cb!=null){Uri[] u=null;if(code==RESULT_OK&&d!=null){if(d.getClipData()!=null){int n=d.getClipData().getItemCount();u=new Uri[n];for(int i=0;i<n;i++)u[i]=d.getClipData().getItemAt(i).getUri();}else if(d.getData()!=null)u=new Uri[]{d.getData()};}cb.onReceiveValue(u);cb=null;}}
 public void onBackPressed(){if(w.canGoBack())w.goBack();else super.onBackPressed();}
}
